#!/usr/bin/env bash
#
# Machinery App registration wizard (ADR-0020 / issue #857).
# Walks the maintainer through: create the repo-scoped GitHub App, install
# it, generate the key, store credentials as repo variable + secret.
# The agent does everything before and after; this script covers only the
# browser steps a human must perform.
#
# Generated by the /wizard skill.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()
WRITTEN_SECRET=()
SKIPPED=()

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open     >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open         >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_path KEY "Prompt" reads a path and loads its file contents into KEY.
# Used for the App's private key .pem (multi-line — one-line entry can't
# represent it).
ask_path() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && return 0
  keyfile="$input"
  if [[ -f "$keyfile" ]]; then
    printf -v "$key" '%s' "$(cat "$keyfile")"
  else
    warn "file not found: $keyfile — paste the path again"
    ask_path "$key" "$prompt"
  fi
}

write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

REPO_URL="https://github.com/RjBiermann/fictional-octo-fiesta"

banner "Machinery App registration (ADR-0020, #857)"

stage "Create the GitHub App"
open_url "https://github.com/settings/apps/new"
step "GitHub App name: e.g. your username + '-machinery' (e.g. RjBiermann-machinery)."
say "  This becomes the bot login '<name>[bot]' — remember it for the last stage."
step "Homepage URL: $REPO_URL"
step "Uncheck 'Webhook → Active' (the pipeline needs no webhooks)."
step "Under 'Repository permissions' set ALL of these to Read and write:"
say "      Contents · Issues · Pull requests · Actions · Workflows"
note "    (Workflows is what lets the lane apply workflow-file patches — the #857 gate.)"
step "Under 'Where can this app be installed?' keep 'Only on this account'."
step "Click 'Create GitHub App'."
pause "Done?"

stage "Capture the Client ID"
say "The app's overview page (github.com/settings/apps/<your-app-name>) shows the"
say "'Client ID' near the top — it looks like Iv1.xxxxxxxx (14+ chars)."
note "The pipeline's token step consumes the Client ID (not the numeric App ID)."
ask MACHINERY_APP_CLIENT_ID "Paste the Client ID:"
write_env MACHINERY_APP_CLIENT_ID "$MACHINERY_APP_CLIENT_ID"
set_var MACHINERY_APP_CLIENT_ID "$MACHINERY_APP_CLIENT_ID"

stage "Capture the bot login"
say "The App login is what relay workflows' 'on.bots' allowlists must accept:"
ask MACHINERY_APP_LOGIN "Paste the app login as <name>[bot] (e.g. RjBiermann-machinery[bot]):"
write_env MACHINERY_APP_LOGIN "$MACHINERY_APP_LOGIN"

stage "Generate and store the private key"
step "On the app's overview page, scroll to 'Private keys' → 'Generate a private key'."
say "  A .pem file downloads automatically."
ask_path MACHINERY_APP_KEY "Paste the path of the downloaded .pem file:"
set_secret MACHINERY_APP_KEY "$MACHINERY_APP_KEY"
note "The key stays in your local .env and the repo secret; never commit the .pem."

stage "Install the App on the repository"
open_url "https://github.com/settings/installations"
step "Find your new App in the list → 'Configure'."
step "Under 'Repository access' select 'Only select repositories' and pick"
say "  RjBiermann/fictional-octo-fiesta."
step "Save. The installation screen lists the permissions you set in stage 1."
pause "Installed?"

step "Optional hygiene: delete the downloaded .pem from Downloads now that the secret is set."

finish
